import { Column, Entity, ForeignKey, Index, PrimaryColumn } from 'typeorm';
import type { Session } from '../../modules/sessions/session.js';
import { UserEntity } from './user.entity.js';

@Entity({ name: 'sessions' })
// By user for listing and revoking; by expiry for the daily purge.
@Index('sessions_user_id_index', ['userId'])
@Index('sessions_expires_at_index', ['expiresAt'])
export class SessionEntity implements Session {
  /** A UUIDv7 generated by the repository, so ids sort by creation time. */
  @PrimaryColumn({ type: 'uuid', primaryKeyConstraintName: 'sessions_pkey' })
  id!: string;

  @Column({ name: 'user_id', type: 'uuid' })
  @ForeignKey(() => UserEntity, { name: 'sessions_user_id_users_id_fk', onDelete: 'CASCADE' })
  userId!: string;

  @Column({ name: 'user_agent', type: 'text', nullable: true })
  userAgent!: string | null;

  @Column({ type: 'text', nullable: true })
  ip!: string | null;

  @Column({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  @Column({ name: 'last_used_at', type: 'timestamptz' })
  lastUsedAt!: Date;

  @Column({ name: 'expires_at', type: 'timestamptz' })
  expiresAt!: Date;

  @Column({ name: 'absolute_expires_at', type: 'timestamptz' })
  absoluteExpiresAt!: Date;

  @Column({ name: 'revoked_at', type: 'timestamptz', nullable: true })
  revokedAt!: Date | null;
}
